// icons.js — ability name -> in-game icon picture.
//
// ABILITY_ICONS (generated by tools/build-ability-icons.py) already holds the
// REAL client icon id for each name — charplan's spell `icon` values are
// spell-effect ids and get resolved through the client's spells.csv at build
// time, so nothing here needs to know about that distinction.
//
// Two skins ship side by side, same ids: img/icons/new/ (the current client
// icons) and img/icons/classic/ (the original-style ones from the client's
// icons/classic folder). The choice is remembered per browser.

import { ABILITY_ICONS } from './ability-icons.js';

const SKIN_KEY = 'chatgator:iconSkin';
export const ICON_SKINS = ['new', 'classic'];

let skin = 'new';
try {
  const saved = localStorage.getItem(SKIN_KEY);
  if (ICON_SKINS.includes(saved)) skin = saved;
} catch { /* localStorage unavailable */ }

export function getIconSkin() { return skin; }

export function setIconSkin(next) {
  if (!ICON_SKINS.includes(next)) return;
  skin = next;
  try { localStorage.setItem(SKIN_KEY, next); } catch { /* ignore */ }
}

// Real icon id for an ability name, or null when we don't have one.
export function iconFor(name) {
  if (!name) return null;
  const id = ABILITY_ICONS[name] ?? ABILITY_ICONS[String(name).trim()];
  return id == null ? null : id;
}

export function iconUrl(id) {
  return id == null ? null : `img/icons/${skin}/${id}.png`;
}

// <img> element for a name, or null. A missing file just hides itself rather
// than leaving a broken-image box.
export function iconImg(name, className = 'ability-icon') {
  const id = iconFor(name);
  if (id == null) return null;
  const img = document.createElement('img');
  img.className = className;
  img.src = iconUrl(id);
  img.alt = '';
  img.loading = 'lazy';
  img.width = 20;
  img.height = 20;
  img.title = `icon ${id}`;
  img.addEventListener('error', () => { img.remove(); });
  return img;
}

// Same thing as an HTML string, for code that builds table rows with
// innerHTML. Empty string when there's no icon.
export function iconHtml(name, className = 'ability-icon') {
  const id = iconFor(name);
  if (id == null) return '';
  return `<img class="${className}" src="${iconUrl(id)}" alt="" loading="lazy" width="20" height="20" title="icon ${id}" onerror="this.remove()">`;
}
